func:
const value = msg.payload;
const required = [
    'node_public_code',
    'metric',
    'value',
    'uncertainty',
    'freshness_factor',
    'calibration_factor',
    'health_factor',
    'scope',
    'signature_valid'
];

for (const field of required) {
    if (!(field in value)) {
        node.error(`Missing required field: ${field}`, msg);
        return null;
    }
}

if (typeof value.node_public_code !== 'string' || value.node_public_code.length === 0) {
    node.error('node_public_code must be a non-empty public asset code.', msg);
    return null;
}

if (!Number.isFinite(value.value) || !Number.isFinite(value.uncertainty)) {
    node.error('Measurement value and uncertainty must be finite.', msg);
    return null;
}

if (value.uncertainty < 0) {
    node.error('Measurement uncertainty must be non-negative.', msg);
    return null;
}

for (const field of ['freshness_factor', 'calibration_factor', 'health_factor']) {
    if (!Number.isFinite(value[field]) || value[field] < 0 || value[field] > 1) {
        node.error(`${field} must be within [0, 1].`, msg);
        return null;
    }
}

const prohibited = ['person_id', 'device_id', 'address', 'biometric', 'augmentation_status'];
for (const field of prohibited) {
    if (field in value) {
        node.error(`Prohibited personal field detected: ${field}`, msg);
        return null;
    }
}

msg.payload = {
    observation: value,
    routing: value.scope === 'community_controlled'
        ? 'community-vault-and-approved-fusion'
        : 'municipal-operational-store-and-approved-fusion',
    action: 'route-for-fusion-only'
};
return msg;
